module freq_divbyfrac(
	input clk, rst_n,
	output clk_div
);
	parameter MUL2_DIV_CLK = 7;
	reg [3:0] cnt;
	wire clk_ave_w, clk_adjust_w;
	// TODO: Add your RTL here
	// ===== Design implementation ===== //

	// Sequential logic
	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			cnt <= 4'd0;
		end else begin
			if(cnt >= MUL2_DIV_CLK-1)
				cnt <= 4'd0;
			else
				cnt <= cnt + 1'b1;
		end
	end

	// Combinational logic
	assign clk_ave_w = (cnt==4'd0 || cnt==4'd4)? 1'b1 : 1'b0;
	assign clk_adjust_w = (cnt==4'd1 || cnt==4'd4)? 1'b1 : 1'b0;
	assign clk_div = clk_ave_w | clk_adjust_w;
endmodule
